import { createApiClient, createConfiguredApiClient } from "./client";
import { createApiFactory } from "./factory";
import { useApiLoad, useApiSend, useApiControls } from "../hooks";
import { GlobalApiConfig, ServiceConfig, RuntimeConfig, MergedApiConfig } from "../types";

/**
 * Type helper for factories used in API modules.
 */
export type ModuleApiFactory = ReturnType<typeof createApiFactory>;

/**
 * Type helper to convert service factory objects into bound service objects.
 */
export type BindServices<T> = {
    [K in keyof T]: T[K] extends (factory: ModuleApiFactory) => infer R
        ? R
        : T[K] extends object
        ? BindServices<T[K]>
        : T[K];
};

/**
 * Helper to bind API services into a single unified hook.
 * Automatically creates the internal client and factory.
 */
export function bindApi<T extends Record<string, any>>(services: T) {
    const client = createApiClient();
    const factory = createApiFactory(client);

    const bind = (obj: any): any => {
        const result: any = {};
        for (const key in obj) {
            if (typeof obj[key] === "function") {
                result[key] = obj[key](factory);
            } else if (typeof obj[key] === "object" && obj[key] !== null) {
                result[key] = bind(obj[key]);
            }
        }
        return result;
    };

    const api = bind(services);

    return {
        ...api,
        useLoad: useApiLoad,
        useSend: useApiSend,
        useControls: useApiControls,
    } as BindServices<T> & {
        useLoad: typeof useApiLoad;
        useSend: typeof useApiSend;
        useControls: typeof useApiControls;
    };
}

/**
 * Enhanced API binder with multi-layer configuration support
 * Supports global, service-level, and runtime-level configuration
 */
export function bindApiWithConfig<T extends Record<string, any>>(
    services: T,
    globalConfig: GlobalApiConfig = {}
) {
    const client = createConfiguredApiClient(globalConfig);
    const factory = createApiFactory(client);

    const bind = (obj: any, serviceConfig: ServiceConfig = {}): any => {
        const result: any = {};
        for (const key in obj) {
            if (typeof obj[key] === "function") {
                // Merge configuration for each service
                const mergedConfig: MergedApiConfig = {
                    ...serviceConfig,
                    globalHeaders: globalConfig.headers || {},
                };
                
                result[key] = obj[key](mergedConfig);
            } else if (typeof obj[key] === "object" && obj[key] !== null) {
                result[key] = bind(obj[key], serviceConfig);
            }
        }
        return result;
    };

    const api = bind(services);

    return {
        ...api,
        useLoad: useApiLoad,
        useSend: useApiSend,
        useControls: useApiControls,
        // Enhanced hooks with configuration support
        useLoadWithConfig: <TParams = any, TResult = any>(
            serviceFactory: any,
            runtimeConfig: RuntimeConfig = {}
        ) => {
            const [execute, state] = useApiLoad(
                serviceFactory({ ...runtimeConfig }),
                runtimeConfig
            );
            return [execute, state];
        },
        useSendWithConfig: <TParams = any, TResult = any>(
            serviceFactory: any,
            runtimeConfig: RuntimeConfig = {}
        ) => {
            const [execute, state] = useApiSend(
                serviceFactory({ ...runtimeConfig }),
                runtimeConfig
            );
            return [execute, state];
        },
    };
}

