import { AxiosInstance } from "axios";
import { ApiRequestConfig } from "../types";

/**
 * Interface for automated CRUD helpers.
 */
export interface ApiCrudHelper<DReq = any, DRes = DReq> {
    list: (config?: ApiRequestConfig) => Promise<DRes[]>;
    get: (id: string | number, config?: ApiRequestConfig) => Promise<DRes>;
    create: (data: DReq, config?: ApiRequestConfig) => Promise<DRes>;
    update: (id: string | number, data: Partial<DReq>, config?: ApiRequestConfig) => Promise<DRes>;
    patch: (id: string | number, data: Partial<DReq>, config?: ApiRequestConfig) => Promise<DRes>;
    remove: (id: string | number, config?: ApiRequestConfig) => Promise<void>;
    upload: (data: any, config?: ApiRequestConfig) => Promise<DRes>;
}

/**
 * Interface for the API Factory object.
 * It is a function that creates CRUD helpers and also has HTTP methods as properties.
 */
export interface ApiFactory {
    <DReq = any, DRes = DReq>(url: string): ApiCrudHelper<DReq, DRes>;
    get<T>(url: string, config?: ApiRequestConfig): Promise<T>;
    post<T>(url: string, data?: any, config?: ApiRequestConfig): Promise<T>;
    put<T>(url: string, data?: any, config?: ApiRequestConfig): Promise<T>;
    delete<T>(url: string, config?: ApiRequestConfig): Promise<T>;
    patch<T>(url: string, data?: any, config?: ApiRequestConfig): Promise<T>;
}

/**
 * Factory for creating standard API wrappers (GET, POST, PUT, DELETE, PATCH).
 * Simplifies Axios instance usage with more concise typing.
 */
export function createApiFactory(client: AxiosInstance): ApiFactory {
    const normalizeConfig = (config?: ApiRequestConfig) => {
        if (!config) return undefined;

        const { query, body, ...rest } = config as any;
        const params = { ...(rest.params || {}), ...(query || {}) };

        const next: any = { ...rest };
        if (Object.keys(params).length) next.params = params;
        if (body !== undefined && next.data === undefined) next.data = body;
        return next;
    };

    const normalizeData = (data: any, config?: ApiRequestConfig) => {
        const nextConfig = normalizeConfig(config) as any;
        const requestData = data !== undefined ? data : nextConfig?.data;
        if (nextConfig && "data" in nextConfig) delete nextConfig.data;
        return { requestData, nextConfig };
    };

    const baseMethods = {
        get<T>(url: string, config?: ApiRequestConfig) {
            const nextConfig = normalizeConfig(config);
            return client.get<T>(url, nextConfig) as unknown as Promise<T>;
        },
        post<T>(url: string, data?: any, config?: ApiRequestConfig) {
            const { requestData, nextConfig } = normalizeData(data, config);
            return client.post<T>(url, requestData, nextConfig) as unknown as Promise<T>;
        },
        put<T>(url: string, data?: any, config?: ApiRequestConfig) {
            const { requestData, nextConfig } = normalizeData(data, config);
            return client.put<T>(url, requestData, nextConfig) as unknown as Promise<T>;
        },
        delete<T>(url: string, config?: ApiRequestConfig) {
            const nextConfig = normalizeConfig(config);
            return client.delete<T>(url, nextConfig) as unknown as Promise<T>;
        },
        patch<T>(url: string, data?: any, config?: ApiRequestConfig) {
            const { requestData, nextConfig } = normalizeData(data, config);
            return client.patch<T>(url, requestData, nextConfig) as unknown as Promise<T>;
        },
    };

    /**
     * Creates a CRUD helper for a specific URL.
     */
    const factory = (<DReq = any, DRes = DReq>(url: string): ApiCrudHelper<DReq, DRes> => {
        const baseUrl = url.endsWith('/') ? url.slice(0, -1) : url;

        return {
            list: (config) => baseMethods.get<DRes[]>(baseUrl, config),
            get: (id, config) => baseMethods.get<DRes>(`${baseUrl}/${id}`, config),
            create: (data, config) => baseMethods.post<DRes>(baseUrl, data, config),
            update: (id, data, config) => baseMethods.put<DRes>(`${baseUrl}/${id}`, data, config),
            patch: (id, data, config) => baseMethods.patch<DRes>(`${baseUrl}/${id}`, data, config),
            remove: (id, config) => baseMethods.delete<void>(`${baseUrl}/${id}`, config),
            upload: (data, config) => {
                const formData = data instanceof FormData ? data : new FormData();
                if (!(data instanceof FormData)) {
                    Object.keys(data).forEach(key => {
                        if (data[key] !== undefined) {
                            formData.append(key, data[key]);
                        }
                    });
                }
                return baseMethods.post<DRes>(baseUrl, formData, {
                    ...config,
                    headers: {
                        ...config?.headers,
                        'Content-Type': 'multipart/form-data',
                    },
                });
            },
        };
    }) as ApiFactory;

    return Object.assign(factory, baseMethods);
}
