import { useCallback, useEffect, useRef, useState } from "react";
import {
    ApiState,
    ApiStatus,
    ApiError,
    ApiRequestControls,
    UseApiErrorPayload,
    UseApiLoadOptions,
    UseApiOptions,
    UseApiSuccessPayload,
} from "../types";

/**
 * Normalisasi error ke format ApiError yang konsisten
 */
function normalizeError(err: any): ApiError {
    const timestamp = new Date();
    
    if (err && typeof err === 'object') {
        // Handle Axios errors
        if (err.response) {
            return {
                message: err.response.data?.message || err.message || 'Request failed',
                code: err.response.status,
                details: err.response.data,
                timestamp,
                originalError: err
            };
        }
        // Handle API errors with message
        if (err.message) {
            return {
                message: err.message,
                code: err.code,
                details: err.details || err,
                timestamp,
                originalError: err
            };
        }
    }
    
    // Fallback for unknown errors
    return {
        message: typeof err === 'string' ? err : 'Unknown error occurred',
        timestamp,
        originalError: err
    };
}

/**
 * Internal hook to manage API state.
 */
function useApiBase<
    TFn extends (...args: any[]) => Promise<any>,
    TResponse = Awaited<ReturnType<TFn>>,
    TError = any,
    B extends string = "default",
    P extends UseApiSuccessPayload = "data",
    EP extends UseApiErrorPayload = "error"
>(
    requestFn: TFn,
    options?: UseApiOptions<TResponse, TError, B, P, EP>
): [
        ApiRequestControls<TFn>,
        ApiState<TResponse, B>
    ] {
    const [state, setState] = useState<ApiState<TResponse, B>>({
        data: options?.initialData ?? null,
        isLoading: false,
        loading: false, // Backward compatibility
        status: "idle",
        error: null,
    } as ApiState<TResponse, B>);

    const abortControllerRef = useRef<AbortController | null>(null);
    const lastArgsRef = useRef<Parameters<TFn> | null>(null);

    const execute = useCallback(async (...args: Parameters<TFn>) => {
        // Cancel previous request if still running
        if (abortControllerRef.current) {
            abortControllerRef.current.abort();
        }

        abortControllerRef.current = new AbortController();
        lastArgsRef.current = args;

        setState((s) => ({ ...s, isLoading: true, loading: true, status: "loading", error: null }));

        try {
            const res = await requestFn(...args);

            // Dynamic data extraction logic
            let finalData: any = res;
            let newState: any = { data: res };

            if (options?.extractor) {
                finalData = options.extractor(res);
                newState = { ...res, data: finalData };
            } else {
                const isObject = res && typeof res === "object" && !Array.isArray(res);
                if (isObject) {
                    const baseModel = options?.baseModel || "default";

                    if (baseModel === "wrapped") {
                        if ("data" in res && res.data && typeof res.data === "object" && "result" in res.data) {
                            const { result, ...lifted } = res.data as any;
                            finalData = result;
                            newState = { ...res, ...lifted, data: finalData };
                        }
                    } else if (baseModel === "data") {
                        if ("data" in res) {
                            finalData = res.data;
                            newState = { ...res, data: finalData };
                        }
                    } else {
                        // "default" logic: try data.result then data
                        if ("data" in res) {
                            const dataField = res.data;
                            if (dataField && typeof dataField === "object" && "result" in dataField) {
                                const { result, ...lifted } = dataField as any;
                                finalData = result;
                                newState = { ...res, ...lifted, data: finalData };
                            } else {
                                finalData = dataField;
                                newState = { ...res, data: finalData };
                            }
                        }
                    }
                }
            }

            setState((s) => ({
                ...s,
                ...newState,
                isLoading: false,
                loading: false,
                status: "success",
                error: null,
            }));

            const payloadMode = (options?.successPayload ?? "data") as UseApiSuccessPayload;
            const payload = (payloadMode === "response" ? res : finalData) as any;
            options?.onSuccess?.(payload);
            options?.onFinally?.();
            return res as TResponse;
        } catch (err) {
            const normalizedError = normalizeError(err);
            setState((s) => ({
                ...s,
                isLoading: false,
                loading: false,
                status: "error",
                error: normalizedError,
            }));
            const errorMode = (options?.errorPayload ?? "error") as UseApiErrorPayload;
            const anyErr = err as any;
            const errorPayload =
                errorMode === "response"
                    ? (anyErr?.response ?? err)
                    : errorMode === "data"
                    ? (anyErr?.response?.data ?? anyErr?.data ?? err)
                    : normalizedError;
            options?.onError?.(errorPayload);
            options?.onFinally?.();
            throw err;
        } finally {
            abortControllerRef.current = null;
        }
    }, [requestFn, options]);

    const refetch = useCallback(async () => {
        if (lastArgsRef.current) {
            return execute(...lastArgsRef.current);
        }
        throw new Error('No previous request to refetch');
    }, [execute]);

    const abort = useCallback(() => {
        if (abortControllerRef.current) {
            abortControllerRef.current.abort();
            abortControllerRef.current = null;
            setState((s) => ({
                ...s,
                isLoading: false,
                loading: false,
                status: "idle",
            }));
        }
    }, []);

    const reset = useCallback(() => {
        abort();
        lastArgsRef.current = null;
        setState({
            data: options?.initialData ?? null,
            isLoading: false,
            loading: false,
            status: "idle",
            error: null,
        } as ApiState<TResponse, B>);
    }, [options?.initialData]);

    const controls = {
        execute,
        refetch,
        abort,
        reset,
    } as ApiRequestControls<TFn>;

    return [controls, state];
}

/**
 * Hook for automated data loading (usually for GET requests).
 */
export function useApiLoad<
    TFn extends (...args: any[]) => Promise<any>,
    TResponse = Awaited<ReturnType<TFn>>,
    TError = any,
    B extends string = "default",
    P extends UseApiSuccessPayload = "data",
    EP extends UseApiErrorPayload = "error"
>(
    requestFn: TFn,
    options?: UseApiLoadOptions<TResponse, Parameters<TFn>, TError, B, P, EP>
): [
        (...args: Parameters<TFn>) => Promise<TResponse>,
        ApiState<TResponse, B>
    ] {
    const [controls, state] = useApiBase(requestFn, options);
    const mounted = useRef(false);

    // Handle enabled/disabled state
    const isEnabled = options?.enabled !== false && !options?.manual;
    
    useEffect(() => {
        if (isEnabled && !mounted.current) {
            mounted.current = true;
            const args = options?.args || [] as any;
            controls.execute(...args);
        }
    }, [isEnabled, options?.args, controls]);

    // Backward compatibility: return execute function as first element
    return [controls.execute, state];
}

/**
 * Hook for manual data sending (usually for POST/PUT/DELETE/PATCH).
 */
export function useApiSend<
    TFn extends (...args: any[]) => Promise<any>,
    TResponse = Awaited<ReturnType<TFn>>,
    TError = any,
    B extends string = "default",
    P extends UseApiSuccessPayload = "data",
    EP extends UseApiErrorPayload = "error"
>(
    requestFn: TFn,
    options?: UseApiOptions<TResponse, TError, B, P, EP>
): [
        (...args: Parameters<TFn>) => Promise<TResponse>,
        ApiState<TResponse, B>
    ] {
    const [controls, state] = useApiBase(requestFn, options);
    
    // Backward compatibility: return execute function as first element
    return [controls.execute, state];
}

/**
 * Hook for full lifecycle control access (new API for advanced use cases).
 * Provides complete control over request lifecycle with execute, refetch, abort, and reset.
 */
export function useApiControls<
    TFn extends (...args: any[]) => Promise<any>,
    TResponse = Awaited<ReturnType<TFn>>,
    TError = any,
    B extends string = "default",
    P extends UseApiSuccessPayload = "data",
    EP extends UseApiErrorPayload = "error"
>(
    requestFn: TFn,
    options?: UseApiOptions<TResponse, TError, B, P, EP>
): [
    ApiRequestControls<TFn>,
    ApiState<TResponse, B>
] {
    return useApiBase(requestFn, options);
}
