import axios, { AxiosInstance } from "axios";
import { ApiClientConfig, GlobalApiConfig } from "../types";

/**
 * Creates an Axios instance with optimal preset configuration.
 * By default, it unwraps response data (returns res.data directly).
 */
export function createApiClient(
  config: ApiClientConfig = {}
): AxiosInstance {
  const {
    unwrapData = true,
    ...axiosConfig
  } = config;

  const client = axios.create({
    baseURL: "/api",
    timeout: 15000,
    headers: {
      "Content-Type": "application/json",
    },
    ...axiosConfig,
  });

  client.interceptors.response.use(
    (res: any) => {
      if (!unwrapData) return res;
      return res.data;
    },
    (error: any) => {
      return Promise.reject(error);
    }
  );

  return client;
}

/**
 * Enhanced API client with global configuration support
 */
export function createConfiguredApiClient(
  globalConfig: GlobalApiConfig = {}
): AxiosInstance {
  const {
    baseURL = "/api",
    timeout = 15000,
    headers = {},
    unwrapData = true,
    interceptors
  } = globalConfig;

  const client = axios.create({
    baseURL,
    timeout,
    headers: {
      "Content-Type": "application/json",
      ...headers,
    },
  });

  // Setup global interceptors if provided
  if (interceptors?.request) {
    client.interceptors.request.use(interceptors.request);
  }
  if (interceptors?.response) {
    client.interceptors.response.use(interceptors.response);
  }

  // Default response interceptor for data unwrapping
  client.interceptors.response.use(
    (res: any) => {
      if (!unwrapData) return res;
      return res.data;
    },
    (error: any) => {
      return Promise.reject(error);
    }
  );

  return client;
}
